import { cursor } from './cursor';
import { gamePaused } from './game';
import { fixedGrid } from './grid';
import { derived } from 'svelte/store';

export const keyboardDisabled = derived(
	[cursor, fixedGrid, gamePaused],
	([$cursor, $fixedGrid, $gamePaused]) => {
		//return ($cursor.x === null && $cursor.y === null) || $fixedGrid[$cursor.y][$cursor.x] || $gamePaused;
	    const isNullCursor = $cursor.x === null || $cursor.y === null;
		const isFixed = $fixedGrid[$cursor.y]?.[$cursor.x] ?? false;
		return isNullCursor || isFixed || $gamePaused;
	},
	false,
);	